# hypothesis: A callback protocol with a positional-only parameter accepts a lambda with a named parameter, but a keyword call to that parameter is rejected by checkers and raises TypeError at runtime.
from typing import Protocol, reveal_type


class Transform(Protocol):
    def __call__(self, value: int, /, *, scale: int = 1) -> int: ...


def apply(f: Transform, v: int) -> int:
    return f(v, scale=2)


def add_one(x: int, /, *, scale: int = 1) -> int:
    return (x + 1) * scale


inc = lambda value, *, scale=1: value + scale
reveal_type(inc)
print('apply lambda', apply(inc, 3))
print('apply def', apply(add_one, 3))


def misuse(f: Transform) -> int:
    return f(value=4)  # expect-error: positional-only parameter passed by keyword


try:
    print('misuse', misuse(inc))
except TypeError as e:
    print('TypeError', type(e).__name__)
